    }
    .section__header {
      text-align: center;
      margin-bottom: 48px;
    }
    .section__header .section__subtitle { margin: 0 auto; }

    /* ── Button ── */
    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 14px 28px;
      border-radius: 50px;
      font-family: 'Nunito', sans-serif;
      font-size: 15px;
      font-weight: 700;
      transition: transform 0.2s, box-shadow 0.2s, background 0.2s;
      min-height: 48px;
    }
    .btn:hover { transform: translateY(-1px); box-shadow: 0 4px 16px rgba(0,0,0,0.12); }
    .btn:active { transform: translateY(0); }
    .btn--primary { background: #2D6A4F; color: #FFF; }
    .btn--primary:hover { background: #245A41; }
    .btn--outline { background: transparent; color: #2D6A4F; border: 2px solid #2D6A4F; }
    .btn--outline:hover { background: #2D6A4F; color: #FFF; }
    .btn--accent { background: #F4A261; color: #FFF; }
    .btn--accent:hover { background: #E58B3D; }

    /* ── Header ── */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(254, 250, 224, 0.92);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid rgba(45, 106, 79, 0.12);
      transition: box-shadow 0.3s;
    }
    .header.scrolled { box-shadow: 0 2px 20px rgba(0,0,0,0.06); }
    .header__inner {
      display: flex;
      align-items: center;
