    .header__mobile-toggle.open span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
    .header__mobile-toggle.open span:nth-child(2) { opacity: 0; }
    .header__mobile-toggle.open span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

    /* ── Hero ── */
    .hero {
      background: linear-gradient(160deg, #FEFAE0 0%, #E8F5E9 50%, #FFF8E1 100%);
      padding: 80px 0 100px;
      text-align: center;
      position: relative;
      overflow: hidden;
    }
    .hero::before {
      content: '';
      position: absolute;
      top: -120px;
      right: -80px;
      width: 400px;
      height: 400px;
      background: radial-gradient(circle, rgba(244, 162, 97, 0.15) 0%, transparent 70%);
      border-radius: 50%;
      pointer-events: none;
    }
    .hero::after {
      content: '';
      position: absolute;
      bottom: -60px;
      left: -40px;
      width: 300px;
      height: 300px;
      background: radial-gradient(circle, rgba(45, 106, 79, 0.10) 0%, transparent 70%);
      border-radius: 50%;
      pointer-events: none;
    }
    .hero__content { position: relative; z-index: 1; }
    .hero__title {
      font-size: clamp(36px, 6vw, 60px);
      font-weight: 900;
      color: #2D6A4F;
      line-height: 1.08;
      margin-bottom: 16px;
      letter-spacing: -1px;
    }
    .hero__subtitle {
      font-size: clamp(16px, 2vw, 19px);
      color: #5C5C5C;
      max-width: 600px;
      margin: 0 auto 32px;
      line-height: 1.55;
    }
    .hero__actions { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; }
    .hero__visual {
      margin-top: 48px;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 16px;
      max-width: 720px;
      margin-left: auto;
      margin-right: auto;
    }
    .hero__visual-item {
      aspect-ratio: 1;
      border-radius: 20px;
      background-size: cover;
      background-position: center;
      box-shadow: 0 8px 24px rgba(0,0,0,0.08);
      transition: transform 0.3s;
    }
    .hero__visual-item:nth-child(1) { background: linear-gradient(135deg, #A8E6CF, #DCEDC1); }
    .hero__visual-item:nth-child(2) { background: linear-gradient(135deg, #FFD3A5, #FD6585); }
    .hero__visual-item:nth-child(3) { background: linear-gradient(135deg, #FFE29F, #FFA99F); }
    .hero__visual-item:nth-child(4) { background: linear-gradient(135deg, #C4E0D4, #89B399); }
    .hero__visual-item:hover { transform: translateY(-4px); }
    .hero__visual-emoji {
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 48px;
      height: 100%;
    }

    /* ── Featured Products Carousel ── */
    .carousel { position: relative; }
    .carousel__track-wrapper { overflow: hidden; margin: 0 -12px; }
    .carousel__track {
      display: flex;
      gap: 20px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      scroll-behavior: smooth;
      padding: 12px 12px 20px;
      -ms-overflow-style: none;
      scrollbar-width: none;
    }
    .carousel__track::-webkit-scrollbar { display: none; }
    .carousel__card {
      flex: 0 0 calc(25% - 15px);
      min-width: 240px;
      scroll-snap-align: start;
      background: #FFF;
      border-radius: 20px;
      overflow: hidden;
      box-shadow: 0 4px 16px rgba(0,0,0,0.06);
      transition: transform 0.3s, box-shadow 0.3s;
    }
    .carousel__card:hover {
      transform: translateY(-6px);
      box-shadow: 0 12px 32px rgba(0,0,0,0.10);
    }
    .carousel__card-image {
      width: 100%;
      aspect-ratio: 4/3;
      background-size: cover;
      background-position: center;
      position: relative;
    }
    .carousel__card:nth-child(1) .carousel__card-image { background: linear-gradient(135deg, #FFE0B2, #FFCC80); }
    .carousel__card:nth-child(2) .carousel__card-image { background: linear-gradient(135deg, #FFF9C4, #FFF176); }
    .carousel__card:nth-child(3) .carousel__card-image { background: linear-gradient(135deg, #D7CCC8, #BCAAA4); }
    .carousel__card:nth-child(4) .carousel__card-image { background: linear-gradient(135deg, #E8F5E9, #A5D6A7); }
    .carousel__card:nth-child(5) .carousel__card-image { background: linear-gradient(135deg, #FFE0B2, #FFAB91); }
    .carousel__card:nth-child(6) .carousel__card-image { background: linear-gradient(135deg, #FFF9C4, #FFE082); }
    .carousel__card:nth-child(7) .carousel__card-image { background: linear-gradient(135deg, #FFCCBC, #FFAB91); }
    .carousel__card:nth-child(8) .carousel__card-image { background: linear-gradient(135deg, #E8D5B7, #D4C4A8); }
    .carousel__card-image-emoji {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 56px;
    }
    .carousel__card-body { padding: 16px 18px 20px; }
    .carousel__card-name {
      font-family: 'Nunito', sans-serif;
      font-size: 16px;
      font-weight: 700;
      color: #2D2D2D;
      margin-bottom: 4px;
    }
    .carousel__card-desc {
      font-size: 13px;
      color: #777;
      margin-bottom: 10px;
      line-height: 1.4;
    }
    .carousel__card-price {
      font-family: 'Nunito', sans-serif;
      font-size: 20px;
      font-weight: 800;
      color: #2D6A4F;
    }
    .carousel__btn {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 48px;
      height: 48px;
      border-radius: 50%;
      background: #FFF;
      box-shadow: 0 4px 16px rgba(0,0,0,0.10);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 20px;
      color: #2D6A4F;
      transition: transform 0.2s, box-shadow 0.2s;
      z-index: 10;
      min-width: 44px;
      min-height: 44px;
    }
    .carousel__btn:hover { transform: translateY(-50%) scale(1.08); box-shadow: 0 6px 24px rgba(0,0,0,0.14); }
    .carousel__btn:active { transform: translateY(-50%) scale(0.96); }
    .carousel__btn--prev { left: -20px; }
    .carousel__btn--next { right: -20px; }
    .carousel__btn:disabled { opacity: 0.3; pointer-events: none; }

    /* ── Seasonal Picks ── */
    .seasonal { background: linear-gradient(180deg, #FEFAE0 0%, #FFF 100%); }
    .seasonal__grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
      gap: 20px;
    }
    .seasonal__card {
      background: #FFF;
      border-radius: 20px;
      padding: 24px;
      box-shadow: 0 4px 16px rgba(0,0,0,0.05);
      display: flex;
      gap: 16px;
      align-items: center;
      transition: transform 0.3s, box-shadow 0.3s;
    }
    .seasonal__card:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 32px rgba(0,0,0,0.08);
    }
    .seasonal__card-icon {
      flex-shrink: 0;
      width: 64px;
      height: 64px;
      border-radius: 16px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 30px;
    }
    .seasonal__card:nth-child(1) .seasonal__card-icon { background: #FFECB3; }
    .seasonal__card:nth-child(2) .seasonal__card-icon { background: #E8F5E9; }
    .seasonal__card:nth-child(3) .seasonal__card-icon { background: #EFEBE9; }
    .seasonal__card:nth-child(4) .seasonal__card-icon { background: #FFF3E0; }
    .seasonal__card-name {
      font-family: 'Nunito', sans-serif;
      font-size: 15px;
      font-weight: 700;
      color: #2D2D2D;
      margin-bottom: 2px;
    }
    .seasonal__card-desc { font-size: 13px; color: #777; margin-bottom: 6px; line-height: 1.4; }
    .seasonal__card-price {
      font-family: 'Nunito', sans-serif;
      font-size: 17px;
      font-weight: 800;
      color: #F4A261;
    }

    /* ── Categories ── */
    .categories__grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
      gap: 20px;
    }
    .category-card {
      position: relative;
      border-radius: 20px;
      overflow: hidden;
      aspect-ratio: 1;
      cursor: pointer;
      box-shadow: 0 4px 16px rgba(0,0,0,0.06);
      transition: transform 0.35s cubic-bezier(0.25, 0.46, 0.45, 0.94), box-shadow 0.35s;
    }
    .category-card:hover {
      transform: scale(1.04);
      box-shadow: 0 16px 40px rgba(0,0,0,0.12);
    }
    .category-card__bg {
      position: absolute;
      inset: 0;
      background-size: cover;
      background-position: center;
      transition: transform 0.5s;
    }
    .category-card:hover .category-card__bg { transform: scale(1.08); }
    .category-card:nth-child(1) .category-card__bg { background: linear-gradient(135deg, #FFE0B2, #FFCC80); }
    .category-card:nth-child(2) .category-card__bg { background: linear-gradient(135deg, #C8E6C9, #81C784); }
    .category-card:nth-child(3) .category-card__bg { background: linear-gradient(135deg, #BBDEFB, #90CAF9); }
    .category-card:nth-child(4) .category-card__bg { background: linear-gradient(135deg, #FFECB3, #FFD54F); }
    .category-card:nth-child(5) .category-card__bg { background: linear-gradient(135deg, #F3E5F5, #CE93D8); }
    .category-card__overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(180deg, rgba(45, 106, 79, 0.0) 40%, rgba(45, 106, 79, 0.82) 100%);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: flex-end;
      padding: 20px;
      opacity: 0;
      transition: opacity 0.35s;
    }
    .category-card:hover .category-card__overlay { opacity: 1; }
    .category-card__emoji {
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      font-size: 52px;
      transition: transform 0.35s, opacity 0.35s;
    }
    .category-card:hover .category-card__emoji {
      transform: translate(-50%, -60%);
      opacity: 0.6;
    }
    .category-card__name {
      font-family: 'Nunito', sans-serif;
      font-size: 18px;
      font-weight: 800;
      color: #FFF;
      text-align: center;
    }
    .category-card__desc {
      font-size: 12px;
      color: rgba(255,255,255,0.85);
      text-align: center;
      margin-top: 2px;
    }

    /* ── Stats Banner ── */
    .stats {
      background: #2D6A4F;
      padding: 56px 0;
    }
    .stats__grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 32px;
      text-align: center;
    }
    .stats__number {
      font-family: 'Nunito', sans-serif;
      font-size: clamp(32px, 4vw, 48px);
      font-weight: 900;
      color: #FFF;
      line-height: 1;
      margin-bottom: 8px;
    }
    .stats__label { font-size: 14px; color: rgba(255,255,255,0.72); line-height: 1.4; }
    .stats__icon { font-size: 28px; margin-bottom: 12px; }

    /* ── Store Locator ── */
    .locator { background: #FFF; }
    .locator__form {
      display: flex;
      gap: 12px;
      max-width: 480px;
      margin: 0 auto 32px;
    }
    .locator__input {
      flex: 1;
      padding: 14px 20px;
      border: 2px solid #E0E0E0;
      border-radius: 50px;
      font-size: 15px;
      background: #FAFAFA;
      transition: border-color 0.2s, box-shadow 0.2s;
      min-height: 48px;
    }
    .locator__input:focus {
      outline: none;
      border-color: #2D6A4F;
      box-shadow: 0 0 0 3px rgba(45, 106, 79, 0.12);
      background: #FFF;
    }
    .locator__results {
      display: none;
      max-width: 640px;
      margin: 0 auto;
    }
    .locator__results.visible { display: block; }
    .locator__result {
      display: flex;
      align-items: center;
      gap: 16px;
      padding: 18px 20px;
      border-radius: 12px;
      transition: background 0.2s;
    }
    .locator__result:hover { background: #F9F9F9; }
    .locator__result + .locator__result { border-top: 1px solid #F0F0F0; }
    .locator__result-distance {
      font-family: 'Nunito', sans-serif;
      font-size: 13px;
      font-weight: 700;
      color: #F4A261;
      background: #FFF3E0;
      padding: 6px 12px;
      border-radius: 50px;
      flex-shrink: 0;
      min-width: 60px;
      text-align: center;
    }
    .locator__result-info { flex: 1; }
    .locator__result-name {
      font-family: 'Nunito', sans-serif;
      font-size: 15px;
      font-weight: 700;
      color: #2D2D2D;
      margin-bottom: 2px;
    }
    .locator__result-address { font-size: 13px; color: #777; }
    .locator__result-hours { font-size: 13px; color: #999; }

    /* ── Newsletter ── */
    .newsletter {
      background: linear-gradient(135deg, #E8F5E9 0%, #FEFAE0 100%);
      padding: 72px 0;
      text-align: center;
    }
    .newsletter__form {
      display: flex;
      gap: 12px;
      max-width: 480px;
      margin: 24px auto 0;
    }
    .newsletter__input {
      flex: 1;
      padding: 14px 20px;
      border: 2px solid #D0E0D0;
      border-radius: 50px;
      font-size: 15px;
      background: #FFF;
      transition: border-color 0.2s, box-shadow 0.2s;
      min-height: 48px;
    }
    .newsletter__input:focus {
      outline: none;
      border-color: #2D6A4F;
      box-shadow: 0 0 0 3px rgba(45, 106, 79, 0.12);
    }
    .newsletter__confirm {
      display: none;
      margin-top: 20px;
      padding: 16px 24px;
      background: #FFF;
      border-radius: 12px;
      font-family: 'Nunito', sans-serif;
      font-size: 15px;
      font-weight: 700;
      color: #2D6A4F;
      box-shadow: 0 4px 16px rgba(0,0,0,0.06);
      max-width: 480px;
      margin-left: auto;
      margin-right: auto;
    }
    .newsletter__confirm.visible { display: block; }

    /* ── Footer ── */
    .footer {
      background: #2D6A4F;
      color: rgba(255,255,255,0.78);
      padding: 64px 0 32px;
    }
    .footer__grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 40px;
      margin-bottom: 40px;
    }
    .footer__col-title {
      font-family: 'Nunito', sans-serif;
      font-size: 13px;
      font-weight: 800;
      color: #FFF;
      text-transform: uppercase;
      letter-spacing: 1.5px;
      margin-bottom: 16px;
    }
    .footer__col ul { list-style: none; }
    .footer__col li { margin-bottom: 8px; }
    .footer__col a {
      font-size: 14px;
      color: rgba(255,255,255,0.65);
      transition: color 0.2s;
    }
    .footer__col a:hover { color: #F4A261; }
    .footer__social {
      display: flex;
      gap: 12px;
      margin-top: 8px;
    }
    .footer__social a {
      width: 40px;
      height: 40px;
      border-radius: 50%;
      background: rgba(255,255,255,0.10);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 18px;
      transition: background 0.2s, transform 0.2s;
      min-width: 44px;
      min-height: 44px;
    }
    .footer__social a:hover { background: rgba(244, 162, 97, 0.35); transform: translateY(-2px); }
    .footer__bottom {
      border-top: 1px solid rgba(255,255,255,0.10);
      padding-top: 24px;
      text-align: center;
      font-size: 13px;
      color: rgba(255,255,255,0.45);
    }

    /* ── Responsive ── */
    @media (max-width: 900px) {
      .hero__visual { grid-template-columns: repeat(2, 1fr); gap: 12px; }
      .carousel__card { flex: 0 0 calc(50% - 10px); min-width: 200px; }
      .carousel__btn--prev { left: 4px; }
      .carousel__btn--next { right: 4px; }
      .stats__grid { grid-template-columns: repeat(2, 1fr); gap: 28px; }
      .footer__grid { grid-template-columns: repeat(2, 1fr); }
    }
    @media (max-width: 640px) {
      .section { padding: 56px 0; }
      .header__nav {
        display: none;
        position: absolute;
        top: 72px;
        left: 0;
        right: 0;
        background: rgba(254, 250, 224, 0.98);
        backdrop-filter: blur(12px);
        flex-direction: column;
        padding: 16px 24px 24px;
        border-bottom: 1px solid rgba(45, 106, 79, 0.12);
        box-shadow: 0 8px 24px rgba(0,0,0,0.06);
