  <script>
    (function() {
      // ── Header scroll state ──
      const header = document.getElementById('header');
      window.addEventListener('scroll', function() {
        header.classList.toggle('scrolled', window.scrollY > 10);
      }, { passive: true });

      // ── Mobile nav toggle ──
      const mobileToggle = document.getElementById('mobileToggle');
      const mainNav = document.getElementById('mainNav');

      mobileToggle.addEventListener('click', function() {
        var isOpen = mainNav.classList.toggle('open');
        mobileToggle.classList.toggle('open');
        mobileToggle.setAttribute('aria-expanded', isOpen);
      });

      // Close mobile nav on link click
      mainNav.querySelectorAll('a').forEach(function(link) {
        link.addEventListener('click', function() {
          mainNav.classList.remove('open');
          mobileToggle.classList.remove('open');
          mobileToggle.setAttribute('aria-expanded', 'false');
        });
      });

      // ── Product Carousel ──
      var track = document.getElementById('carouselTrack');
      var prevBtn = document.getElementById('carouselPrev');
      var nextBtn = document.getElementById('carouselNext');
      var cardEl = track.querySelector('.carousel__card');
      var cardWidth = 0;

      function getScrollAmount() {
        if (!cardEl) return 300;
        var style = getComputedStyle(cardEl);
        return cardEl.offsetWidth + parseInt(style.marginRight || '0') + parseInt(style.marginLeft || '0');
      }

      function updateCarouselButtons() {
        var scrollLeft = track.scrollLeft;
        var maxScroll = track.scrollWidth - track.clientWidth;
        prevBtn.disabled = scrollLeft <= 2;
        nextBtn.disabled = scrollLeft >= maxScroll - 2;
      }

      prevBtn.addEventListener('click', function() {
        track.scrollBy({ left: -getScrollAmount(), behavior: 'smooth' });
      });

      nextBtn.addEventListener('click', function() {
        track.scrollBy({ left: getScrollAmount(), behavior: 'smooth' });
      });

      track.addEventListener('scroll', updateCarouselButtons, { passive: true });
      window.addEventListener('resize', updateCarouselButtons, { passive: true });
      updateCarouselButtons();

      // ── Store Locator ──
      var zipInput = document.getElementById('zipInput');
      var zipSearch = document.getElementById('zipSearch');
      var locatorResults = document.getElementById('locatorResults');

      function showResults() {
        locatorResults.classList.add('visible');
      }

      zipSearch.addEventListener('click', function() {
        if (zipInput.value.trim().length > 0) {
          showResults();
        }
      });

      zipInput.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' && zipInput.value.trim().length > 0) {
          e.preventDefault();
          showResults();
        }
      });

      // ── Newsletter ──
      var newsletterForm = document.getElementById('newsletterForm');
      var emailInput = document.getElementById('emailInput');
      var newsletterConfirm = document.getElementById('newsletterConfirm');

      newsletterForm.addEventListener('submit', function(e) {
        e.preventDefault();
        if (emailInput.value.trim().length > 0 && emailInput.checkValidity()) {
          newsletterForm.style.display = 'none';
          newsletterConfirm.classList.add('visible');
        }
      });

      // ── Smooth scroll for anchor links (fallback for older browsers) ──
      document.querySelectorAll('a[href^="#"]').forEach(function(anchor) {
        anchor.addEventListener('click', function(e) {
          var target = document.querySelector(this.getAttribute('href'));
          if (target) {
            e.preventDefault();
            target.scrollIntoView({ behavior: 'smooth' });
          }
        });
      });
    })();
  </script>
